/**
 * Visual regression gate (spec §13): re-renders every variant via the Rust
 * renderer and compares against committed golden images with pixelmatch.
 *
 * Usage:
 *   pnpm tsx scripts/visual-regression.ts [--update]
 *
 * Goldens live in scripts/golden/ and are generated by
 * `cargo run -p vexillum-render --bin render-goldens -- scripts/golden`.
 * Updating them requires an explicit `--update` (CI gates on diffs > 0.1%).
 */
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const { PNG } = require("pngjs") as typeof import("pngjs");
const pixelmatchModule = require("pixelmatch") as { default: typeof import("pixelmatch").default };
const pixelmatch = pixelmatchModule.default ?? (pixelmatchModule as unknown as typeof import("pixelmatch").default);

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, "..");
const goldenDir = resolve(here, "golden");
const candidateDir = resolve(here, "../target/golden-candidates");
const UPDATE = process.argv.includes("--update");

function cargoPath(): string {
  if (existsSync(`${process.env.HOME}/.cargo/bin/cargo`)) {
    return `${process.env.HOME}/.cargo/bin/cargo`;
  }
  return "cargo";
}

function renderCandidates(): void {
  mkdirSync(candidateDir, { recursive: true });
  execFileSync(
    cargoPath(),
    ["run", "-q", "-p", "vexillum-render", "--bin", "render-goldens", "--", candidateDir],
    { cwd: repo, stdio: "inherit" },
  );
}

function compare(): { failures: string[]; total: number; worst: { id: string; pct: number } | null } {
  const manifest = JSON.parse(
    readFileSync(join(repo, "crates/templates/assets/registry.json"), "utf8"),
  ) as { variants: Array<{ id: string; title: string }> };

  const failures: string[] = [];
  let total = 0;
  let worst: { id: string; pct: number } | null = null;

  for (const v of manifest.variants) {
    const ext = existsSync(join(goldenDir, `${v.id}.gif`)) ? "gif" : "png";
    const goldenPath = join(goldenDir, `${v.id}.${ext}`);
    const candidatePath = join(candidateDir, `${v.id}.${ext}`);
    if (!existsSync(goldenPath)) {
      failures.push(`${v.id}: golden missing (run with --update)`);
      continue;
    }
    if (!existsSync(candidatePath)) {
      failures.push(`${v.id}: candidate render failed`);
      continue;
    }
    if (ext === "gif") {
      // animated: compare byte-level (deterministic encoding) instead of frames
      const a = readFileSync(goldenPath);
      const b = readFileSync(candidatePath);
      total++;
      if (!a.equals(b)) {
        if (UPDATE) {
          writeFileSync(goldenPath, b);
        } else {
          failures.push(`${v.id}: gif bytes changed`);
        }
      }
      continue;
    }
    const golden = PNG.sync.read(readFileSync(goldenPath));
    const candidate = PNG.sync.read(readFileSync(candidatePath));
    if (golden.width !== candidate.width || golden.height !== candidate.height) {
      failures.push(
        `${v.id}: size changed ${golden.width}x${golden.height} → ${candidate.width}x${candidate.height}`,
      );
      continue;
    }
    const diff = new PNG({ width: golden.width, height: golden.height });
    const mismatched = pixelmatch(golden.data, candidate.data, diff.data, golden.width, golden.height, {
      threshold: 0.1,
    });
    const pct = (mismatched / (golden.width * golden.height)) * 100;
    total++;
    if (!worst || pct > worst.pct) worst = { id: v.id, pct };
    if (pct > 0.1) {
      if (UPDATE) {
        writeFileSync(goldenPath, PNG.sync.write(candidate));
      } else {
        failures.push(`${v.id}: ${pct.toFixed(3)}% pixels differ (> 0.1%)`);
      }
    }
  }
  return { failures, total, worst };
}

if (UPDATE) {
  console.log("updating goldens from fresh renders…");
  if (!existsSync(goldenDir)) mkdirSync(goldenDir, { recursive: true });
  renderCandidates();
  execFileSync("cp", ["-r", `${candidateDir}/.`, goldenDir], { cwd: repo });
  console.log(`goldens updated in ${goldenDir}`);
  process.exit(0);
}

renderCandidates();
const { failures, total, worst } = compare();
console.log(`compared ${total} variants; worst drift: ${worst ? `${worst.id} ${worst.pct.toFixed(4)}%` : "n/a"}`);
if (failures.length > 0) {
  console.error(`visual regression FAILED (${failures.length}):`);
  for (const f of failures.slice(0, 20)) console.error(" -", f);
  process.exit(1);
}
console.log("visual regression PASSED");
